changeSet.sql:
ALTER TABLE modeling_materialization_dispatch ADD CONSTRAINT ck_modeling_materialization_dispatch CHECK ( btrim(tenant_id) <> '' AND candidate_version > 0 AND attempt > 0 AND btrim(execution_target_key) <> '' AND btrim(airflow_dag_id) <> '' AND btrim(airflow_run_id) <> '' AND artifact_bundle_checksum ~ '^[0-9a-f]{64}$' AND ( scoped_bundle_checksum IS NULL OR scoped_bundle_checksum ~ '^[0-9a-f]{64}$' ) AND ( ( runtime_token_digest IS NULL AND runtime_token_expires_at IS NULL ) OR ( runtime_token_digest ~ '^sha256:[0-9a-f]{64}$' AND runtime_token_expires_at IS NOT NULL ) ) AND status IN ( 'PENDING', 'CLAIMED', 'SUBMITTED', 'UNKNOWN', 'BLOCKED', 'COMPLETED', 'FAILED' ) AND dispatch_attempts >= 0 AND ( (profile_lease_id IS NULL AND runtime_consumed_at IS NULL) OR (profile_lease_id IS NOT NULL AND runtime_consumed_at IS NOT NULL) ) );
CREATE UNIQUE INDEX uk_materialization_dispatch_candidate_attempt ON modeling_materialization_dispatch ( tenant_id, candidate_id, candidate_version, attempt );
CREATE UNIQUE INDEX uk_materialization_dispatch_runtime_token ON modeling_materialization_dispatch (runtime_token_digest) WHERE runtime_token_digest IS NOT NULL;
CREATE INDEX idx_materialization_dispatch_ready ON modeling_materialization_dispatch ( status, next_attempt_at, created_at, id ) WHERE status IN ('PENDING', 'CLAIMED', 'UNKNOWN');
INSERT INTO modeling_materialization_dispatch ( id, tenant_id, candidate_id, candidate_version, attempt, execution_target_key, airflow_dag_id, airflow_run_id, artifact_bundle_checksum, scoped_bundle_checksum, status, dispatch_attempts, next_attempt_at, recovered, created_at, last_modified_at ) SELECT pr.pipeline_run_group_id, pr.tenant_id, pr.release_candidate_id, pr.release_candidate_version, pr.attempt, c.execution_target_key, min(pr.airflow_dag_id), min(pr.airflow_run_id), min(pr.artifact_bundle_checksum), min(pr.scoped_bundle_checksum), CASE WHEN bool_and(pr.status = 'QUEUED') THEN 'PENDING' ELSE 'SUBMITTED' END, 0, coalesce(min(pr.created_date), current_timestamp), false, coalesce(min(pr.created_date), current_timestamp), coalesce(max(pr.last_modified_date), current_timestamp) FROM modeling_pipeline_run pr JOIN modeling_model_release_candidate c ON c.tenant_id = pr.tenant_id AND c.id = pr.release_candidate_id WHERE pr.run_purpose = 'RELEASE_BUILD' AND pr.pipeline_run_group_id IS NOT NULL GROUP BY pr.pipeline_run_group_id, pr.tenant_id, pr.release_candidate_id, pr.release_candidate_version, pr.attempt, c.execution_target_key ON CONFLICT (id) DO NOTHING;

rollback.sql:
DO $$
BEGIN
    IF EXISTS (
        SELECT 1
          FROM modeling_materialization_dispatch
         WHERE status IN (
            'PENDING', 'CLAIMED', 'SUBMITTED', 'UNKNOWN'
         )
    ) THEN
        RAISE EXCEPTION 'ROLLBACK_BLOCKED_ACTIVE_MATERIALIZATION_DISPATCH_EXISTS';
    END IF;
END $$;
